export type Card = { monster: string; rank?: number };

const SPHINX = "sphinx";
const THREE_TYPES = 3;
const BASE_POINTS = 1;
const POINTS_PER_TYPE_BEYOND_THREE = 2;
const POINTS_WITHIN_THREE_TYPES = 1;

const countDistinctMonsterTypes = (cards: Card[]): number =>
  new Set(cards.map((card) => card.monster)).size;

// A Sphinx scores against the types it can see, which are the types of every
// other card in the army: it does not count itself, but a second Sphinx is
// another card and so does count.
const cardsSeenBy = (army: Card[], sphinxPosition: number): Card[] =>
  army.filter((_, position) => position !== sphinxPosition);

// "Sphinx — 1 point. 2 per type beyond three, else 1."
const pointsForSphinx = (visibleCards: Card[]): number => {
  const visibleTypes = countDistinctMonsterTypes(visibleCards);
  return (
    BASE_POINTS +
    (visibleTypes > THREE_TYPES
      ? POINTS_PER_TYPE_BEYOND_THREE * (visibleTypes - THREE_TYPES)
      : POINTS_WITHIN_THREE_TYPES)
  );
};

export const scoreArmy = (army: Card[]): number =>
  army.reduce(
    (score, card, position) =>
      card.monster === SPHINX
        ? score + pointsForSphinx(cardsSeenBy(army, position))
        : score,
    0,
  );

import { scoreArmy, type Card } from "./sphinx-score.js";

const readStdin = async (): Promise<string> => {
  let input = "";
  process.stdin.setEncoding("utf8");
  for await (const chunk of process.stdin) input += chunk;
  return input;
};

const main = async (): Promise<void> => {
  const { army } = JSON.parse(await readStdin()) as { army: Card[] };
  process.stdout.write(JSON.stringify({ score: scoreArmy(army) }));
};

await main();
